import pandas as pd,numpy as np,itertools,time
from sklearn.model_selection import ShuffleSplit
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor
from catboost import CatBoostRegressor
D=pd.read_csv('b3_htsteel_toughness_pareto_train.csv'); X=D.iloc[:,:-2]; Y=D.iloc[:,-2:].values
lo=Y.min(0); span=Y.max(0)-lo

def hv(p):
 p=np.maximum(p,0); p=p[np.argsort(p[:,0])]; best=0.; area=0.
 for x,y in p[::-1]:
  if y>best: area += x*(y-best); best=y
 return area

def front(p): return np.array([i for i,x in enumerate(p) if not np.any(np.all(p>=x,1)&np.any(p>x,1))])
def choose(p,k=5):
 ix=front(p)
 best=(-1,None)
 if len(ix)>=k:
  for z in itertools.combinations(ix,k):
   q=hv(p[list(z)])
   if q>best[0]:best=(q,z)
  return list(best[1])
 # fill dominated by max individual HV; they do not affect predicted HV
 left=[i for i in np.argsort(-(p[:,0]*p[:,1])) if i not in ix]
 return list(ix)+left[:k-len(ix)]
ss=ShuffleSplit(20,test_size=100,random_state=2609)
res={n:[] for n in ['ET1','ET2','RF','Cat','ETCat','allblend','ETmix']}; regs={n:[] for n in res}
for z,(a,b) in enumerate(ss.split(X)):
 mods={
 'ET1':ExtraTreesRegressor(n_estimators=350,max_features=1.,min_samples_leaf=1,n_jobs=-1,random_state=100+z),
 'ET2':ExtraTreesRegressor(n_estimators=350,max_features=1.,min_samples_leaf=2,n_jobs=-1,random_state=200+z),
 'RF':RandomForestRegressor(n_estimators=350,max_features=.8,min_samples_leaf=1,n_jobs=-1,random_state=300+z),
 'Cat':CatBoostRegressor(iterations=600,depth=6,learning_rate=.04,l2_leaf_reg=5,loss_function='MultiRMSE',verbose=False,random_seed=400+z,thread_count=4)}
 ps={}
 for n,m in mods.items():m.fit(X.iloc[a],Y[a]);ps[n]=m.predict(X.iloc[b])
 ps['ETCat']=.5*ps['ET1']+.5*ps['Cat']; ps['allblend']=np.mean([ps[x] for x in ['ET1','ET2','RF','Cat']],0); ps['ETmix']=.5*ps['ET1']+.5*ps['ET2']
 # normalize with global fixed ranges, realistic from available train differs little
