  res[n].append(score);regs[n].append(oracle-score)
 print(z+1,'oracle',round(oracle,3),'best',max((round(res[n][-1],3),n) for n in res))
print('\nSUMMARY')
for n in res: print(n,'HV mean/se',round(np.mean(res[n]),4),round(np.std(res[n])/np.sqrt(20),4),'median',round(np.median(res[n]),4),'regret',round(np.mean(regs[n]),4),'wins',sum(res[n][i]==max(res[x][i] for x in res) for i in range(20)))
